//! 🎛️ Retirement CPU is independent of retained currencies and survives genuine nested failure.
use super::*;
use std::sync::atomic::{AtomicBool,Ordering};
use crate::{RetainedCloneGrant,RetainedCloneProgress};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
struct Bank{remaining:RetainedCloneGrant,cpu:u64,turns:usize,maximum_cpu:u64}
impl Bank{
 fn new(v:&serde_json::Value)->Self{let s=&v["stock"];let n=|k|s[k].as_u64().unwrap()as usize;Self{remaining:RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copy"),maximum_capacity_bytes:n("capacity"),maximum_release_bytes:n("release"),maximum_depth:n("depth")},cpu:0,turns:0,maximum_cpu:v["maximumCpuWork"].as_u64().unwrap()}}
 fn post_work(&mut self,work:u64){self.cpu=self.cpu.checked_add(work).unwrap();assert!(self.cpu<=self.maximum_cpu);}
 fn turn<T:RetireOwned>(&mut self,owner:&mut ControlledRetirement<T>)->Result<RetainedCloneStep,ValueError>{let grant=RetainedCloneGrant{maximum_items:1,..self.remaining};let(result,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.step(grant));let p=owner.step_progress();assert!(p.fits(grant));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);self.remaining.maximum_items-=p.copied_items;self.remaining.maximum_copy_bytes-=p.copied_bytes;self.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;self.remaining.maximum_release_bytes-=p.released_bytes;self.post_work(owner.last_turn_work());self.turns+=1;result}
 fn finish<T:RetireOwned>(&mut self,mut owner:ControlledRetirement<T>,limit:usize){while !owner.terminal_is_empty(){assert!(self.turns<limit);self.turn(&mut owner).unwrap();}let(_,heap)=crate::allocation_testing::observe_retirement_allocations(||drop(owner));assert_eq!(heap,(0,0));}
}
#[test]
fn actual_controlled_work_denials_and_terminal_queries_do_not_mint_cpu(){
 let v=fixture();let mut bank=Bank::new(&v);let mut owner=ControlledRetirement::new(vec![17_u128,29,43]).unwrap();
 while !owner.terminal_is_empty(){assert!(bank.turns<v["maximumTurns"].as_u64().unwrap()as usize);let d=owner.next_demand(bank.remaining.maximum_copy_bytes).unwrap();for axis in v["axes"].as_array().unwrap(){let mut grant=RetainedCloneGrant{maximum_items:1,..bank.remaining};match axis.as_str().unwrap(){"items"=>grant.maximum_items=0,"copy" if d.copy_bytes>0=>grant.maximum_copy_bytes=d.copy_bytes-1,"capacity" if d.capacity_bytes>0=>grant.maximum_capacity_bytes=d.capacity_bytes-1,"release" if d.release_bytes>0=>grant.maximum_release_bytes=d.release_bytes-1,"depth" if d.depth>0=>grant.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.select(bank.remaining.maximum_copy_bytes).unwrap().step(grant));assert_eq!(turn.work,v["expected"]["deniedCpu"].as_u64().unwrap());assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert_eq!(owner.next_demand(bank.remaining.maximum_copy_bytes).unwrap(),d);}
 let result=bank.turn(&mut owner).unwrap();assert!(owner.last_turn_work()>0,"admitted real frontier must advance");assert_eq!(owner.step_progress(),result.progress());}
 let(result,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.step(Default::default()).unwrap());assert!(matches!(result,RetainedCloneStep::Complete(_)));assert_eq!(owner.last_turn_work(),v["expected"]["terminalCpu"].as_u64().unwrap());assert_eq!(owner.step_progress(),Default::default());assert_eq!(heap,(0,0));assert!(bank.cpu>0);bank.finish(owner,v["maximumTurns"].as_u64().unwrap()as usize);
}
static CANCEL:AtomicBool=AtomicBool::new(false);
struct FailureOwner{source:String}
struct FailureCursor{owner:ControlledRetirement<String>,pointer:usize,failed:bool,done:bool}
impl RetireOwned for FailureOwner{
 fn retirement(self)->Box<dyn RetirementCursor>{let pointer=self.source.as_ptr()as usize;Box::new(FailureCursor{owner:ControlledRetirement::retain(self.source),pointer,failed:false,done:false})}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<FailureCursor>())}
 fn controlled_retirement_supported()->bool{true}
}
impl RetirementCursor for FailureCursor{
 fn next_demand(&self,body:usize)->Result<crate::RetirementDemand,ValueError>{if self.done{return Ok(Default::default());}if !CANCEL.load(Ordering::SeqCst)||self.owner.terminal_is_empty(){return Ok(crate::RetirementDemand{depth:1,..Default::default()});}let mut d=self.owner.next_demand(body)?;d.depth+=1;Ok(d)}
 fn close_step(&mut self,grant:RetainedCloneGrant)->RetirementStep{if self.done{return RetirementStep::BudgetExhausted;}if grant.maximum_items==0||grant.maximum_depth==0{return RetirementStep::BudgetExhausted;}if !CANCEL.load(Ordering::SeqCst){let work=u64::from(!self.failed);if !self.failed{assert_eq!(self.owner.original().unwrap().as_ptr()as usize,self.pointer);assert!(!self.owner.original().unwrap().is_empty());self.failed=true;}return RetirementStep::Failure(ValueError::literal(ValueRefusalKind::InvalidValue,"original nested source was rejected"),work);}if self.owner.terminal_is_empty(){self.done=true;return RetirementStep::Complete(1);}let result=self.owner.step(RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant});let work=self.owner.last_turn_work();match result{Ok(step)=>RetirementStep::Progress(step.progress(),work),Err(error)=>RetirementStep::Failure(error,work)}}
 fn terminal_is_empty(&self)->bool{self.done}
 fn next_close_byte_demand(&self)->Option<usize>{if !CANCEL.load(Ordering::SeqCst)||self.owner.terminal_is_empty(){Some(0)}else{self.owner.next_release_byte_demand().ok()}}
 fn next_work_byte_demand(&self)->Result<usize,ValueError>{if !CANCEL.load(Ordering::SeqCst)||self.owner.terminal_is_empty(){Ok(0)}else{self.owner.next_copy_byte_demand()}}
 fn next_birth_bytes(&self,body:usize)->Option<usize>{if !CANCEL.load(Ordering::SeqCst)||self.owner.terminal_is_empty(){Some(0)}else{self.owner.next_capacity_byte_demand(body).ok()}}
 fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.next_demand(0)?.depth)}
 fn terminal_release_bytes(&self)->Option<usize>{Some(size_of::<Self>())}
}
#[test]
fn actual_nested_new_and_cached_failures_report_independent_work_and_keep_source_until_paid_close(){
 CANCEL.store(false,Ordering::SeqCst);let v=fixture();let mut bank=Bank::new(&v);let mut owner=ControlledRetirement::new(FailureOwner{source:v["expected"]["source"].as_str().unwrap().into()}).ok().unwrap();let mut failure=None;
 while failure.is_none(){assert!(bank.turns<v["maximumTurns"].as_u64().unwrap()as usize);if let Err(error)=bank.turn(&mut owner){failure=Some(error);}}
 assert_eq!(failure.as_ref().unwrap().message,"original nested source was rejected");let new_cpu=owner.last_turn_work();assert_eq!(new_cpu,v["expected"]["newFailureCpu"].as_u64().unwrap());let receipt=owner.step_progress();assert_eq!(failure.as_ref().unwrap().retained_progress(),receipt);let cached=bank.turn(&mut owner).unwrap_err();let cached_cpu=owner.last_turn_work();assert_eq!(cached_cpu,v["expected"]["cachedCpu"].as_u64().unwrap());assert_eq!(cached.message,failure.unwrap().message);assert_eq!(cached.retained_progress(),Default::default());assert_eq!(owner.step_progress(),Default::default());
 let actual=serde_json::json!({"deniedCpu":0,"cachedCpu":cached_cpu,"newFailureCpu":new_cpu,"terminalCpu":0,"source":v["expected"]["source"].as_str().unwrap()});let independent:serde_json::Value=serde_json::from_str(&serde_json::to_string(&actual).unwrap()).unwrap();assert_eq!(independent,v["expected"]);CANCEL.store(true,Ordering::SeqCst);bank.finish(owner,v["maximumTurns"].as_u64().unwrap()as usize);
}

#[test]
fn actual_page_reservation_cpu_distinguishes_denial_existing_capacity_and_real_failed_attempt(){
 struct Excess;
 unsafe impl crate::list::PageAllocation for Excess{fn reserve<T>(owner:&mut Vec<T>,slots:usize)->Result<(),std::collections::TryReserveError>{owner.try_reserve_exact(slots*2)}}
 let v=fixture();let mut bank=Bank::new(&v);let mut list=crate::list::PagedList::<u8,{usize::MAX}>::default();let quote=list.next_allocation_bytes().unwrap();
 let(step,heap)=crate::allocation_testing::observe_retirement_allocations(||list.reserve_one(quote-1).unwrap());assert_eq!(step.work,v["expected"]["deniedCpu"].as_u64().unwrap());assert_eq!(step,Default::default());assert_eq!(heap,(0,0));
 let(error,heap)=crate::allocation_testing::observe_retirement_allocations(||list.reserve_one_using::<Excess>(quote).unwrap_err());assert_eq!(error.work,v["expected"]["newFailureCpu"].as_u64().unwrap());assert_eq!(error.kind,crate::list::PagedListRefusalKind::InvariantViolated);assert_eq!(heap,(error.allocated_bytes,0));bank.remaining.maximum_items-=1;bank.remaining.maximum_capacity_bytes-=error.allocated_bytes;bank.post_work(error.work);bank.finish(ControlledRetirement::new(list).ok().unwrap(),v["maximumTurns"].as_u64().unwrap()as usize);let mut list=crate::list::PagedList::<u8,{usize::MAX}>::default();while !list.has_reserved_slot(){let quote=list.next_allocation_bytes().unwrap();let(step,heap)=crate::allocation_testing::observe_retirement_allocations(||list.reserve_one(quote).unwrap());assert_eq!(step.work,1);assert_eq!(heap,(step.allocated_bytes,0));bank.remaining.maximum_items-=1;bank.remaining.maximum_capacity_bytes-=step.allocated_bytes;bank.post_work(step.work);}
 let quote=list.next_allocation_bytes().unwrap();let(step,heap)=crate::allocation_testing::observe_retirement_allocations(||list.reserve_one(quote).unwrap());assert_eq!(step.work,v["expected"]["cachedCpu"].as_u64().unwrap());assert_eq!(step,Default::default());assert_eq!(heap,(0,0));bank.finish(ControlledRetirement::new(list).ok().unwrap(),v["maximumTurns"].as_u64().unwrap()as usize);
}

#[test]
fn actual_typed_birth_returns_independent_cpu_and_same_source_across_refusal_and_allocator_failure(){
 let v=fixture();let mut bank=Bank::new(&v);let mut source=v["expected"]["source"].as_str().unwrap().to_owned();let pointer=source.as_ptr();let bytes=controlled_retirement_birth_bytes::<String>();let grant=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:bytes,maximum_depth:1,..Default::default()};
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||admit_typed_controlled_retirement(source,denied));assert_eq!(turn.work,v["expected"]["deniedCpu"].as_u64().unwrap());assert_eq!(heap,(0,0));let(_,original)=turn.result.err().unwrap();source=original;assert_eq!(source.as_ptr(),pointer);}
 let((turn,attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||admit_typed_controlled_retirement(source,grant)));assert_eq!(attempts,v["birth"]["refusedAttempts"].as_u64().unwrap()as usize);assert_eq!(turn.work,v["expected"]["newFailureCpu"].as_u64().unwrap());assert_eq!(heap,(0,0));let(error,original)=turn.result.err().unwrap();assert_eq!(error.kind.as_str(),v["birth"]["refusalKind"].as_str().unwrap());assert_eq!(original.as_ptr(),pointer);source=original;bank.post_work(turn.work);
 let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||admit_typed_controlled_retirement(source,grant));assert_eq!(turn.work,1);let(mut owner,receipt)=turn.result.ok().unwrap();assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),heap);assert_eq!(owner.original().unwrap().as_ptr(),pointer);bank.remaining.maximum_items-=receipt.copied_items;bank.remaining.maximum_capacity_bytes-=receipt.retained_capacity_bytes;bank.post_work(turn.work);while !owner.terminal_is_empty(){assert!(bank.turns<v["maximumTurns"].as_u64().unwrap()as usize);bank.turn(owner.as_mut()).unwrap();}bank.finish(ControlledRetirement::retain(owner),v["maximumTurns"].as_u64().unwrap()as usize);
}

#[test]
fn actual_shared_birth_keeps_the_original_arc_on_real_null_and_uses_one_bank_through_dynamic_close(){
 let v=fixture();let mut bank=Bank::new(&v);let source=std::sync::Arc::new(v["expected"]["source"].as_str().unwrap().to_owned());let pointer=std::sync::Arc::as_ptr(&source);let bytes=crate::retirement::arc_custody::shared_retirement_birth_bytes::<String>();let grant=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:bytes,maximum_depth:1,..Default::default()};
 let((turn,attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||crate::retirement::arc_custody::admit_shared_retirement(source,grant,false)));assert_eq!(attempts,1);assert_eq!(turn.work,1);assert_eq!(heap,(0,0));let(error,source)=turn.result.err().unwrap();assert_eq!(error.kind.as_str(),v["birth"]["refusalKind"].as_str().unwrap());assert_eq!(std::sync::Arc::as_ptr(&source),pointer);bank.post_work(turn.work);
 let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||crate::retirement::arc_custody::admit_shared_retirement(source,grant,false));assert_eq!(turn.work,1);let(owner,p)=turn.result.ok().unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.remaining.maximum_items-=p.copied_items;bank.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.post_work(turn.work);let mut slot=Some(owner);
 while let Some(owner)=slot.as_ref(){assert!(bank.turns<v["maximumTurns"].as_u64().unwrap()as usize);let d=crate::factory_ticket_demands(owner,bank.remaining.maximum_copy_bytes).unwrap();let grant=RetainedCloneGrant{maximum_items:bank.remaining.maximum_items.min(1),maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert!(grant.maximum_items>0&&grant.maximum_depth<=bank.remaining.maximum_depth);assert!(grant.maximum_capacity_bytes<=bank.remaining.maximum_capacity_bytes&&grant.maximum_copy_bytes<=bank.remaining.maximum_copy_bytes&&grant.maximum_release_bytes<=bank.remaining.maximum_release_bytes);let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||crate::select_factory_ticket(&mut slot,bank.remaining.maximum_copy_bytes).unwrap().step(grant));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.remaining.maximum_items-=p.copied_items;bank.remaining.maximum_copy_bytes-=p.copied_bytes;bank.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.remaining.maximum_release_bytes-=p.released_bytes;bank.post_work(turn.work);bank.turns+=1;}
 let(_,heap)=crate::allocation_testing::observe_retirement_allocations(||drop(slot));assert_eq!(heap,(0,0));
}

#[test]
fn actual_factory_authority_birth_and_failure_keep_the_same_capability_and_forward_exact_work(){
 let v=fixture();let mut bank=Bank::new(&v);let source=std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(v["birth"]["factoryValue"].as_u64().unwrap()as usize));let address=std::sync::Arc::as_ptr(&source)as usize;let(mut owner,heap)=crate::allocation_testing::observe_retirement_allocations(||crate::FactoryAuthority::new(source));assert_eq!(heap,(0,0));assert_eq!(owner.factory_address(),address);let d=owner.demands(bank.remaining.maximum_copy_bytes).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};
 let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_items:0,..grant}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.factory_address(),address);
 let((turn,attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||owner.step(grant)));assert_eq!(attempts,1);assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap_err().kind.as_str(),v["birth"]["refusalKind"].as_str().unwrap());assert_eq!(heap,(0,0));assert_eq!(owner.factory_address(),address);bank.post_work(turn.work);
 while !owner.terminal_is_empty(){assert!(bank.turns<v["maximumTurns"].as_u64().unwrap()as usize);let d=owner.demands(bank.remaining.maximum_copy_bytes).unwrap();let grant=RetainedCloneGrant{maximum_items:bank.remaining.maximum_items.min(1),maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert!(grant.maximum_items>0&&grant.maximum_depth<=bank.remaining.maximum_depth&&grant.maximum_capacity_bytes<=bank.remaining.maximum_capacity_bytes&&grant.maximum_copy_bytes<=bank.remaining.maximum_copy_bytes&&grant.maximum_release_bytes<=bank.remaining.maximum_release_bytes);let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.step(grant));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.remaining.maximum_items-=p.copied_items;bank.remaining.maximum_copy_bytes-=p.copied_bytes;bank.remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.remaining.maximum_release_bytes-=p.released_bytes;bank.post_work(turn.work);bank.turns+=1;}
 let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.step(Default::default()));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));let(_,heap)=crate::allocation_testing::observe_retirement_allocations(||drop(owner));assert_eq!(heap,(0,0));
}
